from pathlib import Path

path = Path("app/static/app.js")
text = path.read_text(encoding="utf-8")


def replace_once(old: str, new: str, label: str) -> None:
    global text
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one marker, found {count}")
    text = text.replace(old, new, 1)


if "function renderHarmony(job)" in text:
    required = (
        "function hydrateCompletedHarmonies(jobs)",
        'data-action="harmony"',
        "job.harmony?.status",
        "function harmonyStageText(stage,status)",
    )
    if all(marker in text for marker in required):
        print("harmonic frontend already patched")
        raise SystemExit(0)
    raise SystemExit("partial harmonic frontend patch detected")

