old_announcement = '''const state=`${job.status}:${job.stage}:${job.message}:${job.analysis?.status}:${job.separation?.status}:${job.separation?.stage}:${job.separation?.message}:${job.separation?.runtime?.state}:${job.transcription?.status}:${job.transcription?.stage}:${job.transcription?.message}:${job.interpretation?.status}:${job.interpretation?.stage}:${job.interpretation?.message}`;'''
